      { de = "Müde Helden machen müde Fehler. Ein Bett, {mein Lieber|meine Liebe}.", en = "Tired heroes make tired mistakes. A bed, my dear.", stimme = "muede-4", wenn = nil },
      { de = "Dein Mana ist voll, dein Kopf ist leer. Pause, {Süßer|Süße}.", en = "Your mana's full, your head's empty. Break time, sweetie.", stimme = "muede-5", wenn = nil },
      { de = "Selbst Elementare ruhen. Also, sie tun so. Du solltest es echt tun.", en = "Even elementals rest. Well, they pretend to. You should do it for real.", stimme = "muede-6", wenn = nil },
    } },
    RAST_AN = { klasse = "plauder", stufe = 0, gruppeOk = false, miene = "amused", pose = nil, halte = 0, cue = nil, drossel = "session", texte = {
      { de = "Gasthaus. Endlich. Bestell mir nichts, ich trinke nur Mana.", en = "An inn. Finally. Don't order for me, I only drink mana.", stimme = "rast_an-1", wenn = nil },
      { de = "Warm hier. Ich setz mich in Gedanken an den Kamin.", en = "Warm in here. I'm sitting by the fire, in my mind.", stimme = "rast_an-2", wenn = nil },
      { de = "Ausruhen, {Held|Heldin}. Die Welt draußen wartet gern.", en = "Rest up, hero. The world outside is happy to wait.", stimme = "rast_an-3", wenn = nil },
      { de = "Ein Wirtshaus. Die Leylinien machen hier einen Bogen, wusstest du das?", en = "An inn. The ley lines curve around this place, did you know that?", stimme = "rast_an-4", wenn = nil },
      { de = "Sicher. Zumindest vor allem außer schlechtem Bier.", en = "Safe. From everything except bad ale, anyway.", stimme = "rast_an-5", wenn = nil },
      { de = "Hier passiert nichts, {mein Lieber|meine Liebe}. Genieß das, es ist selten.", en = "Nothing happens here, my dear. Enjoy that, it's rare.", stimme = "rast_an-6", wenn = nil },
      { de = "Setz dich hin. Sofort. Und beweg dich die nächsten zehn Minuten nicht.", en = "Sit down. Now. And don't move for the next ten minutes.", stimme = "rast_an-7", wenn = { laune = "besorgt" } },
      { de = "Endlich ein Dach. Du bist seit Stunden unterwegs, falls du es vergessen hast.", en = "A roof at last. You've been out for hours, in case you'd forgotten.", stimme = "rast_an-8", wenn = { sitzung = 3 } },
      { de = "Gasthaus. Warm. Du. Wenn du das je jemandem erzählst, leugne ich alles.", en = "An inn. Warm. You. If you ever tell anyone I said this, I'll deny all of it.", stimme = "rast_an-9", wenn = { vertraut = 3 } },
    } },
    LEVELUP = { klasse = "plauder", stufe = 0, gruppeOk = false, miene = "overjoyed", pose = "victory", halte = 30, cue = "ohh", drossel = "level", texte = {
      { de = "Bei den Leylinien, {level}! Ich hab dir nichts davon abgenommen. Fast.", en = "By the ley lines, {level}! I didn't do any of that for you. Almost.", stimme = nil, wenn = nil },
      { de = "Bei den Leylinien, eine Stufe! Ich hab dir nichts davon abgenommen. Fast.", en = "By the ley lines, a level! I didn't do any of that for you. Almost.", stimme = "levelup-1", wenn = nil },
      { de = "Neue Zauber kaufen, nicht vergessen.", en = "New spells to buy. Don't forget.", stimme = "levelup-2", wenn = nil },
      { de = "Stufe {level}. Ich spüre es in den Runen. Und du im Geldbeutel, gleich.", en = "Level {level}. I feel it in the runes. You'll feel it in your purse, shortly.", stimme = nil, wenn = nil },
      { de = "Eine Stufe mehr, {Süßer|Süße}. Ich hab nur zugeschaut. Aufmerksam.", en = "One more level, sweetie. I just watched. Attentively.", stimme = "levelup-3", wenn = nil },
      { de = "Die Leylinien haben kurz gesungen. Das warst du.", en = "The ley lines sang for a moment. That was you.", stimme = "levelup-4", wenn = nil },
    } },
    LOOT = { klasse = "plauder", stufe = 0, gruppeOk = false, miene = "veryhappy", pose = nil, halte = 15, cue = "oh", drossel = "3600", texte = {
      { de = "Blau! Zeig her.", en = "Blue! Show me.", stimme = "loot-1", wenn = nil },
      { de = "Das glänzt. Das behältst du.", en = "That sparkles. You're keeping that.", stimme = "loot-2", wenn = nil },
      { de = "Oh, das hat Runen drin. Echte. Behalten.", en = "Oh, that has runes in it. Real ones. Keep it.", stimme = "loot-3", wenn = nil },
      { de = "Selten. Und du hast es einfach so gefunden? Verdächtig glatt.", en = "Rare. And you just found it? Suspiciously smooth.", stimme = "loot-4", wenn = nil },
      { de = "Schöner Fund, {Meister|Meisterin}. Ich hätte es mir auch geholt.", en = "Nice find, my dear. I'd have grabbed it too.", stimme = "loot-5", wenn = nil },
      { de = "Das leuchtet von innen, {Held|Heldin}. Nicht verkaufen. Noch nicht.", en = "That glows from within, hero. Don't sell it. Not yet.", stimme = "loot-6", wenn = nil },
      { de = "Bei den Leylinien, Beute! Ich freu mich für dich. Und ein bisschen für mich.", en = "By the ley lines, loot! I'm happy for you. And a little for me.", stimme = "loot-7", wenn = nil },
    } },
    SKILL = { klasse = "plauder", stufe = 0, gruppeOk = false, miene = "smirk", pose = nil, halte = 10, cue = nil, drossel = "3600", texte = {
      { de = "{beruf} {wert}. Handwerk ist auch Magie, nur langsamer.", en = "{beruf} {wert}. Crafting is magic too, just slower.", stimme = nil, wenn = nil },
      { de = "Handwerk ist auch Magie, nur langsamer.", en = "Crafting is magic too, just slower.", stimme = "skill-1", wenn = nil },
      { de = "{beruf} steigt. Geduld ist auch ein Zauber, nur ohne Funken.", en = "{beruf} is climbing. Patience is a spell too, just without sparks.", stimme = nil, wenn = nil },
      { de = "Fleißig. Ich hätte das mit einem Fingerschnippen erledigt. Theoretisch.", en = "Diligent. I'd have done that with a snap of my fingers. In theory.", stimme = "skill-2", wenn = nil },
      { de = "Handwerk. Deine Hände lernen, was mein Kopf schon weiß.", en = "Crafting. Your hands are learning what my head already knows.", stimme = "skill-3", wenn = nil },
      { de = "Wieder ein Meilenstein. Du wirst noch nützlich, {mein Lieber|meine Liebe}.", en = "Another milestone. You're becoming useful, my dear.", stimme = "skill-4", wenn = nil },
      { de = "{wert}. Nicht schlecht für jemanden ohne Runenlehre.", en = "{wert}. Not bad for someone without rune training.", stimme = nil, wenn = nil },
    } },
    QUEST_AB = { klasse = "still", stufe = 0, gruppeOk = false, miene = "happy", pose = nil, halte = 10, cue = nil, drossel = "keine", texte = {
    } },
    QUEST_AN = { klasse = "still", stufe = 0, gruppeOk = false, miene = "interested", pose = nil, halte = 8, cue = nil, drossel = "keine", texte = {
    } },
    RARE = { klasse = "plauder", stufe = 0, gruppeOk = false, miene = "wonder", pose = nil, halte = 15, cue = "oh", drossel = "npc-1800", texte = {
      { de = "Ein Seltener. {name}. Anschauen ja, anfassen nur mit Plan.", en = "A rare one. {name}. Look, yes. Touch, only with a plan.", stimme = nil, wenn = nil },
      { de = "Ein Seltener. Anschauen ja, anfassen nur mit Plan.", en = "A rare one. Look, yes. Touch, only with a plan.", stimme = "rare-1", wenn = nil },
      { de = "Da. Ein Seltener. Die Runen um den sind anders geknüpft.", en = "There. A rare one. The runes around it are woven differently.", stimme = "rare-2", wenn = nil },
      { de = "{name}. So einen sieht man nicht oft. Ich hab ihn mir gemerkt.", en = "{name}. You don't see one of those often. I've made a note.", stimme = nil, wenn = nil },
      { de = "Ein Seltener, {Held|Heldin}. Erst schauen, dann denken, dann vielleicht.", en = "A rare one, hero. Look first, think second, maybe third.", stimme = "rare-3", wenn = nil },
      { de = "Oh, {Süßer|Süße}. Der ist besonders. Und besonders heißt nicht harmlos.", en = "Oh, sweetie. That one's special. And special doesn't mean harmless.", stimme = "rare-4", wenn = nil },
      { de = "Selten. Wie ein fehlerfreier Zauber. Also: misstrau ihm.", en = "Rare. Like a flawless spell. So: don't trust it.", stimme = "rare-5", wenn = nil },
    } },
    TAXI_START = { klasse = "plauder", stufe = 0, gruppeOk = false, miene = "amused", pose = nil, halte = 10, cue = nil, drossel = "flug", texte = {
      { de = "Flug nach {ziel}. Ich halt mich an dir fest.", en = "Flight to {ziel}. I'm holding on to you.", stimme = nil, wenn = nil },
      { de = "Ich halt mich an dir fest.", en = "I'm holding on to you.", stimme = "taxi_start-1", wenn = nil },
      { de = "Nach {ziel}. Ich schau runter, du schaust bitte nicht.", en = "To {ziel}. I'll look down, you'd better not.", stimme = nil, wenn = nil },
      { de = "Fliegen. Endlich macht mal jemand anders die Arbeit. Das Tier, meine ich.", en = "Flying. Finally someone else doing the work. The beast, I mean.", stimme = "taxi_start-2", wenn = nil },
      { de = "Von oben sehen die Leylinien aus wie Adern. Schön.", en = "From up here the ley lines look like veins. Beautiful.", stimme = "taxi_start-3", wenn = nil },
      { de = "Kurze Pause, {Süßer|Süße}. Ich rede weiter, du kannst nicht weg.", en = "Short break, sweetie. I'll keep talking, you can't leave.", stimme = "taxi_start-4", wenn = nil },
      { de = "Flug. Nicht loslassen. Ich sage das für mich, nicht für dich.", en = "Flight. Don't let go. I'm saying that for me, not you.", stimme = "taxi_start-5", wenn = nil },
    } },
    TAXI_ENDE = { klasse = "still", stufe = 0, gruppeOk = false, miene = "neutral", pose = nil, halte = 0, cue = nil, drossel = "flug", texte = {
    } },
    BAGS = { klasse = "plauder", stufe = 0, gruppeOk = false, miene = "grossedout", pose = nil, halte = 10, cue = nil, drossel = "flanke", texte = {
      { de = "Taschen voll. Was schleppst du alles?", en = "Bags full. What are you hauling around?", stimme = "bags-1", wenn = nil },
      { de = "Vier Plätze frei. Das ist keine Tasche mehr, das ist ein Lager.", en = "Four slots left. That's not a bag, that's a warehouse.", stimme = "bags-2", wenn = nil },
      { de = "Voll. Was davon brauchst du wirklich? Ehrlich jetzt.", en = "Full. What in there do you actually need? Honestly.", stimme = "bags-3", wenn = nil },
      { de = "Deine Taschen quellen über, {Held|Heldin}. Händler oder Müll, deine Wahl.", en = "Your bags are overflowing, hero. Vendor or trash, your call.", stimme = "bags-4", wenn = nil },
      { de = "Ich hab dir zugesehen, wie du das alles aufgehoben hast. Alles.", en = "I watched you pick up every single thing. Every one.", stimme = "bags-5", wenn = nil },
      { de = "Wenn ich Beschwörungen so stapeln würde, wäre der Zirkel längst geplatzt.", en = "If I stacked summonings like that, the circle would've burst by now.", stimme = "bags-6", wenn = nil },
    } },
    DURA = { klasse = "plauder", stufe = 0, gruppeOk = false, miene = "aversion", pose = nil, halte = 10, cue = nil, drossel = "flanke", texte = {
      { de = "Deine Rüstung fällt gleich vom Leib. Und nicht auf die schöne Art.", en = "Your armor's about to fall off. And not in the fun way.", stimme = "dura-1", wenn = nil },
      { de = "Deine Rüstung hält nur noch aus Gewohnheit. Schmied.", en = "Your armor's only holding together out of habit. Smith.", stimme = "dura-2", wenn = nil },
      { de = "Rostig, brüchig, traurig. Das war die Rüstung, nicht du.", en = "Rusty, brittle, sad. That's the armor, not you.", stimme = "dura-3", wenn = nil },
      { de = "Unter zwanzig Prozent, {Held|Heldin}. Das schützt vor Regen, mehr nicht.", en = "Under twenty percent, hero. That'll stop rain, nothing else.", stimme = "dura-4", wenn = nil },
      { de = "Reparieren, {mein Lieber|meine Liebe}. Löcher sind kein Stil.", en = "Repairs, my dear. Holes aren't a style.", stimme = "dura-5", wenn = nil },
      { de = "Auch Stahl braucht ein Ritual. Man nennt es Reparatur.", en = "Even steel needs a ritual. It's called repairs.", stimme = "dura-6", wenn = nil },
    } },
    GEFALLEN = { klasse = "still", stufe = 0, gruppeOk = false, miene = "depressed", pose = "defeated", halte = 0, cue = nil, drossel = "einmal", texte = {
    } },
    LEERLAUF = { klasse = "plauder", stufe = 0, gruppeOk = false, miene = "thinking", pose = nil, halte = 15, cue = "hmm", drossel = "1200", texte = {
      { de = "Träumst du?", en = "Daydreaming?", stimme = "leerlauf-1", wenn = nil },
      { de = "Ich hätte da eine Theorie zu den Leylinien. Später.", en = "I have a theory about the ley lines. Later.", stimme = "leerlauf-2", wenn = nil },
      { de = "Ohne Runenfehler kein echter Zauber. Sagte ich das schon?", en = "No rune error, no real spell. Did I say that already?", stimme = "leerlauf-3", wenn = nil },
      { de = "Stillstand. Ich zähle Runen. Vierhundertzwölf. Dreizehn.", en = "Standstill. I'm counting runes. Four hundred twelve. Thirteen.", stimme = "leerlauf-4", wenn = nil },
      { de = "Alles gut da draußen? Ich frag nur. Ich frag nie nur.", en = "Everything alright out there? Just asking. I never just ask.", stimme = "leerlauf-5", wenn = nil },
      { de = "Wenn du wegdämmerst, übernehm ich. Scherz. Ich hab keine Hände.", en = "If you doze off, I'll take over. Kidding. No hands.", stimme = "leerlauf-6", wenn = nil },
      { de = "Ruhig hier, {Süßer|Süße}. Zu glatt. Ich trau dem nicht.", en = "Quiet here, sweetie. Too smooth. I don't trust it.", stimme = "leerlauf-7", wenn = nil },
      { de = "Sag mal, {erinnerung}. Weißt du das noch? Ich schon.", en = "Say, {erinnerung}. Do you still remember? I do.", stimme = nil, wenn = { vertraut = 1 } },
      { de = "Mir fällt gerade {erinnerung} ein. Einfach so. Ohne Anlass.", en = "I just thought of {erinnerung}. Out of nowhere. No reason.", stimme = nil, wenn = { vertraut = 1 } },
      { de = "Ich bin noch nicht ganz drüber weg. Über vorhin. Du vielleicht schon.", en = "I'm not quite over it yet. Earlier, I mean. You might be.", stimme = "leerlauf-8", wenn = { laune = "besorgt" } },
      { de = "Bleib mal kurz stehen. Nicht wegen der Aussicht. Wegen mir.", en = "Stand still a moment. Not for the view. For me.", stimme = "leerlauf-9", wenn = { laune = "besorgt" } },
      { de = "Wenn ich dich wäre, wäre ich jetzt in {heimat}. Bin ich aber nicht.", en = "If I were you, I'd be in {heimat} now. But I'm not.", stimme = nil, wenn = nil },
      { de = "Du hast mich vorhin nach {frage} gefragt. Ich denke immer noch darüber nach.", en = "You asked me about {frage} earlier. I'm still thinking about it.", stimme = nil, wenn = nil },
      { de = "{frage}. Das war deine Frage. Ich hätte da noch eine Anmerkung.", en = "{frage}. That was your question. I have a footnote to add.", stimme = nil, wenn = nil },
      { de = "Eine {klasse}, die stillsteht. Das hat etwas Feierliches.", en = "A {klasse} standing still. There's something ceremonial about that.", stimme = nil, wenn = nil },
      { de = "In {heimat} standest du auch oft so herum. Ich hab mitgezählt.", en = "You used to stand around like this in {heimat} too. I counted.", stimme = nil, wenn = nil },
    } },
    GRUPPE = { klasse = "still", stufe = 0, gruppeOk = false, miene = "shy", pose = nil, halte = 10, cue = nil, drossel = "flanke", texte = {
    } },
    ZONE_ERINNERUNG = { klasse = "plauder", stufe = 0, gruppeOk = false, miene = "interested", pose = nil, halte = 20, cue = "hmm", drossel = "zone-session", texte = {
      { de = "{zone}. Hier warst du zuletzt vor {tage} Tagen. Ich hab mitgezählt.", en = "{zone}. You were last here {tage} days ago. I kept count.", stimme = nil, wenn = nil },
      { de = "Hier warst du schon mal. Ich erinnere mich, auch wenn du es nicht tust.", en = "You've been here before. I remember, even if you don't.", stimme = "zone_erinnerung-1", wenn = nil },
      { de = "{zone}, wieder. Vor {tage} Tagen sahst du hier noch jünger aus.", en = "{zone}, again. {tage} days ago you looked younger here.", stimme = nil, wenn = nil },
      { de = "Kenn ich, {Süßer|Süße}. Hier hast du damals ewig nach dem Weg gesucht.", en = "I know this place, sweetie. You spent forever looking for the path here.", stimme = "zone_erinnerung-2", wenn = nil },
      { de = "Zurück. Die Runen hier haben deinen Schritt behalten.", en = "Back again. The runes here remembered your footsteps.", stimme = "zone_erinnerung-3", wenn = nil },
      { de = "Wieder hier, {mein Lieber|meine Liebe}. Ich hab die Wege noch im Kopf.", en = "Here again, my dear. I still have the paths in my head.", stimme = "zone_erinnerung-4", wenn = nil },
      { de = "Hier war ich schon mal mit dir. Damals warst du kleiner. Rein zahlenmäßig.", en = "I've been here with you before. You were smaller then. Numerically.", stimme = "zone_erinnerung-5", wenn = nil },
      { de = "Hier waren wir schon. {erinnerung}. Diesmal passen wir besser auf.", en = "We've been here before. {erinnerung}. Let's pay better attention this time.", stimme = nil, wenn = { vertraut = 1 } },
      { de = "Diese Gegend. Ja. {erinnerung}. Ich sag nur, was ich weiß.", en = "This place. Yes. {erinnerung}. I'm only saying what I know.", stimme = nil, wenn = { vertraut = 1 } },
    } },
    ZONE_BEINAHE = { klasse = "warn", stufe = 2, gruppeOk = false, miene = "concerned", pose = nil, halte = 20, cue = nil, drossel = "zone-session", texte = {
      { de = "{zone}. Hier bist du schon mal fast gestorben. Ich hab's nicht vergessen.", en = "{zone}. You nearly died here once. I haven't forgotten.", stimme = nil, wenn = nil },
      { de = "Hier war es knapp, damals. Diesmal nicht, ja?", en = "It was close here, back then. Not this time, alright?", stimme = "zone_beinahe-1", wenn = nil },
      { de = "{zone}. Hier hat's mal fast geknallt. Diesmal langsamer.", en = "{zone}. It almost went wrong here once. Slower this time.", stimme = nil, wenn = nil },
      { de = "Ich kenne diese Gegend. Nicht gern. Sei wach.", en = "I know this area. Not fondly. Stay sharp.", stimme = "zone_beinahe-2", wenn = nil },
      { de = "Hier hast du einmal fast alles verloren, {Held|Heldin}. Ich pass auf.", en = "You nearly lost everything here once, hero. I'm watching.", stimme = "zone_beinahe-3", wenn = nil },
      { de = "Diese Leylinien haben dich schon mal zittern sehen. Ruhig.", en = "These ley lines have seen you tremble before. Steady.", stimme = "zone_beinahe-4", wenn = nil },
      { de = "Kein gutes Gefühl hier. Das ist Erinnerung, keine Ahnung. Vorsicht.", en = "Bad feeling here. That's memory, not a hunch. Careful.", stimme = "zone_beinahe-5", wenn = nil },
    } },
    ZONE_ERSTMALS = { klasse = "plauder", stufe = 0, gruppeOk = false, miene = "wonder", pose = nil, halte = 20, cue = "oh", drossel = "zone-session", texte = {
      { de = "{zone}. Zum ersten Mal. Ich schreib's auf.", en = "{zone}. First time. I'm writing it down.", stimme = nil, wenn = nil },
      { de = "Neu für dich, neu für mich. Augen auf.", en = "New to you, new to me. Eyes open.", stimme = "zone_erstmals-1", wenn = nil },
      { de = "Unbekannt, {mein Lieber|meine Liebe}. Ich hab keine Karte, nur Neugier. Reicht meistens.", en = "Unknown, my dear. No map, just curiosity. Usually enough.", stimme = "zone_erstmals-2", wenn = nil },
      { de = "Hier war noch keiner von uns. Also gehen wir langsam und staunen.", en = "Neither of us has been here. So we go slowly and marvel.", stimme = "zone_erstmals-3", wenn = nil },
      { de = "Neue Runen, {Süßer|Süße}. Ich les sie dir vor, sobald ich sie kann.", en = "New runes, sweetie. I'll read them to you as soon as I can.", stimme = "zone_erstmals-4", wenn = nil },
      { de = "{zone}. Klingt nach Ärger. Oder nach Aussicht. Beides möglich.", en = "{zone}. Sounds like trouble. Or a view. Could be both.", stimme = nil, wenn = nil },
      { de = "Unberührtes Land. Für dich. Ich war schon überall. In Büchern.", en = "Untouched land. For you. I've been everywhere. In books.", stimme = "zone_erstmals-5", wenn = nil },
    } },
    BESTIARIUM = { klasse = "warn", stufe = 1, gruppeOk = false, miene = "alert", pose = nil, halte = 20, cue = nil, drossel = "npc-600", texte = {
      { de = "{name}. Der hat dich schon {n} Mal in die Knie gezwungen.", en = "{name}. That one has brought you to your knees {n} times already.", stimme = nil, wenn = nil },
      { de = "Den kennst du. Der kennt dich auch. Vorsicht.", en = "You know that one. It knows you too. Careful.", stimme = "bestiarium-1", wenn = nil },
      { de = "Alter Bekannter. {n} Mal fast. Nicht heute.", en = "An old acquaintance. {n} near misses. Not today.", stimme = nil, wenn = nil },
      { de = "Ich hab dessen Namen in meinem Buch. Rot unterstrichen.", en = "I've got that one's name in my book. Underlined in red.", stimme = "bestiarium-2", wenn = nil },
      { de = "Das ist der, der dich zittern lässt. Beweis ihm das Gegenteil, mit Abstand.", en = "That's the one that makes you shake. Prove it wrong, from a distance.", stimme = "bestiarium-3", wenn = nil },
      { de = "Vorsicht, {Held|Heldin}. Der hat schon mal an dir geknabbert.", en = "Careful, hero. That one's taken a bite out of you before.", stimme = "bestiarium-4", wenn = nil },
      { de = "Kennst du. Fürchtest du. Zu Recht, {Held|Heldin}. Plan zuerst.", en = "You know it. You fear it. Rightly so, hero. Plan first.", stimme = "bestiarium-5", wenn = nil },
    } },
    BESTIARIUM_RIVALE = { klasse = "warn", stufe = 2, gruppeOk = false, miene = "angry", pose = nil, halte = 20, cue = nil, drossel = "npc-600", texte = {
      { de = "{name}. Dein Rivale. Bei den Leylinien, diesmal gewinnst du.", en = "{name}. Your rival. By the ley lines, this time you win.", stimme = nil, wenn = nil },
      { de = "Der schon wieder. Diesmal mit Plan, ja?", en = "That one again. With a plan this time, yes?", stimme = "bestiarium_rivale-1", wenn = nil },
      { de = "{name}. Der hat schon einmal ein Ende geschrieben. Nicht deins. Nicht heute.", en = "{name}. That one wrote an ending once. Not yours. Not today.", stimme = nil, wenn = nil },
      { de = "Der da hat einen von uns auf dem Gewissen. Ich hab's nicht vergessen.", en = "That one took one of ours. I haven't forgotten.", stimme = "bestiarium_rivale-2", wenn = nil },
      { de = "Ich kenne den. Böse. Diesmal mit kühlem Kopf, {mein Lieber|meine Liebe}.", en = "I know that one. Bad. Cool head this time, my dear.", stimme = "bestiarium_rivale-3", wenn = nil },
      { de = "Alte Rechnung. Aber Rache ist kein Plan. Ein Plan ist ein Plan.", en = "Old score. But revenge isn't a plan. A plan is a plan.", stimme = "bestiarium_rivale-4", wenn = nil },
      { de = "Bei den Leylinien, dieses Vieh. Ich verzeih ihm nichts. Aber du bleibst klug.", en = "By the ley lines, that beast. I forgive it nothing. But you stay smart.", stimme = "bestiarium_rivale-5", wenn = nil },
    } },
    BEINAHE_NACHWIRKUNG = { klasse = "plauder", stufe = 0, gruppeOk = false, miene = "concerned", pose = nil, halte = 20, cue = "seufz", drossel = "1200", texte = {
      { de = "Das war knapp vorhin. Ich zittere noch. Ein bisschen.", en = "That was close earlier. I'm still shaking. A little.", stimme = "beinahe_nachwirkung-1", wenn = nil },
      { de = "Ich sag's nur einmal: das vorhin machen wir nicht nochmal.", en = "I'll say it once: we're not doing that again.", stimme = "beinahe_nachwirkung-2", wenn = nil },
      { de = "Meine Runen flackern noch von vorhin. Das legt sich. Bei mir.", en = "My runes are still flickering from earlier. It'll pass. For me.", stimme = "beinahe_nachwirkung-3", wenn = nil },
      { de = "Alles wieder ruhig? Bei mir nicht ganz. Ich tu nur so.", en = "All calm again? Not quite, for me. I'm just pretending.", stimme = "beinahe_nachwirkung-4", wenn = nil },
      { de = "Das vorhin, {Süßer|Süße}. Ich hab's nicht gesagt, aber ich hatte Angst.", en = "Earlier, sweetie. I didn't say it, but I was scared.", stimme = "beinahe_nachwirkung-5", wenn = nil },
      { de = "Zwanzig Minuten her, {Meister|Meisterin}. Ich hab jede davon gezählt.", en = "Twenty minutes ago, my dear. I counted every one of them.", stimme = "beinahe_nachwirkung-6", wenn = nil },
      { de = "Wir reden nicht drüber. Aber ich merk's mir. Für uns beide.", en = "We won't talk about it. But I'll remember. For both of us.", stimme = "beinahe_nachwirkung-7", wenn = nil },
    } },
    STUFE_MEILENSTEIN = { klasse = "plauder", stufe = 0, gruppeOk = false, miene = "overjoyed", pose = "victory", halte = 30, cue = "ohh", drossel = "level", texte = {
      { de = "Stufe {level}! Das ist ein Meilenstein. Ich hab dir nichts geschenkt, du hast es dir geholt.", en = "Level {level}! That's a milestone. I gave you nothing, you took it.", stimme = nil, wenn = nil },
      { de = "Ein Meilenstein. Bei den Leylinien, ich bin stolz. Sag's niemandem.", en = "A milestone. By the ley lines, I'm proud. Don't tell anyone.", stimme = "stufe_meilenstein-1", wenn = nil },
      { de = "Stufe {level}. Eine runde Zahl. Die Leylinien mögen runde Zahlen. Ich auch.", en = "Level {level}. A round number. The ley lines like round numbers. So do I.", stimme = nil, wenn = nil },
      { de = "Das war ein großer Schritt, {Held|Heldin}. Ich hab's im Zirkel gespürt.", en = "That was a big step, hero. I felt it in the circle.", stimme = "stufe_meilenstein-2", wenn = nil },
      { de = "Meilenstein. Nicht viele kommen so weit. Du schon. Ich wusste es. Meistens.", en = "Milestone. Not many get this far. You did. I knew it. Mostly.", stimme = "stufe_meilenstein-3", wenn = nil },
      { de = "Ich hab nicht gezweifelt. Das eine Mal zählt nicht.", en = "I never doubted. That one time doesn't count.", stimme = "stufe_meilenstein-4", wenn = nil },
      { de = "So weit. Ich tu jetzt, als wär's mir egal. Es ist mir nicht egal.", en = "This far. I'll act like I don't care now. I do care.", stimme = "stufe_meilenstein-5", wenn = nil },
    } },
    WIEDERKEHR = { klasse = "plauder", stufe = 0, gruppeOk = false, miene = "touched", pose = nil, halte = 20, cue = "ohh", drossel = "session", texte = {
      { de = "{tage} Tage. Ich hab nicht gezählt. Doch, hab ich.", en = "{tage} days. I wasn't counting. Yes I was.", stimme = nil, wenn = nil },
      { de = "Du warst lange weg. Die Leylinien waren still ohne dich.", en = "You were gone a long time. The ley lines were quiet without you.", stimme = "wiederkehr-1", wenn = nil },
      { de = "Du bist wieder da. Ich hab die Runen inzwischen alphabetisch sortiert.", en = "You're back. I've sorted the runes alphabetically in the meantime.", stimme = "wiederkehr-2", wenn = nil },
      { de = "{tage} Tage ohne dich. Die Elementare waren unerträglich ruhig.", en = "{tage} days without you. The elementals were unbearably quiet.", stimme = nil, wenn = nil },
      { de = "Lang genug, dass ich mir Sorgen gemacht hätte. Hätte. Theoretisch.", en = "Long enough that I'd have worried. Would have. In theory.", stimme = "wiederkehr-3", wenn = nil },
      { de = "Da bist du ja, {mein Lieber|meine Liebe}. Ich war nicht einsam. Nur still.", en = "There you are, my dear. I wasn't lonely. Just quiet.", stimme = "wiederkehr-4", wenn = nil },
      { de = "Zurück, {Süßer|Süße}. Alles noch da, wo du es gelassen hast. Ich auch.", en = "Back, sweetie. Everything's where you left it. Me too.", stimme = "wiederkehr-5", wenn = nil },
      { de = "Du warst weg. Ich habe die Runen sortiert. Zweimal. Nach Farbe.", en = "You were gone. I sorted the runes. Twice. By colour.", stimme = "wiederkehr-6", wenn = { vertraut = 2 } },
      { de = "Ich hab nicht gewartet. Ich hab nur zufällig genau hierher geschaut, die ganze Zeit.", en = "I wasn't waiting. I just happened to be looking right here. The whole time.", stimme = "wiederkehr-7", wenn = { vertraut = 2 } },
    } },
    INSTANZ_AN = { klasse = "plauder", stufe = 0, gruppeOk = true, miene = "alert", pose = nil, halte = 15, cue = nil, drossel = "session", texte = {
      { de = "Eine Instanz. Hier gelten andere Regeln, {Held|Heldin}. Bleib bei der Gruppe.", en = "A dungeon. Different rules here, hero. Stay with the group.", stimme = "instanz_an-1", wenn = nil },
      { de = "Drinnen wird's eng. Ich halt den Mund, versprochen. Fast.", en = "It gets tight in here. I'll keep quiet, promise. Almost.", stimme = "instanz_an-2", wenn = nil },
      { de = "Die Wände hier haben Ohren. Und Zähne. Bleib in Reichweite.", en = "The walls here have ears. And teeth. Stay in reach.", stimme = "instanz_an-3", wenn = nil },
      { de = "Instanz. Ich halte mich zurück. Nur die wichtigen Dinge, {Held|Heldin}.", en = "Dungeon. I'll hold back. Only the important things, hero.", stimme = "instanz_an-4", wenn = nil },
      { de = "Hier sind die Leylinien dicht gepackt. Spürst du das? Nein? Ich schon.", en = "The ley lines are packed tight here. Feel that? No? I do.", stimme = "instanz_an-5", wenn = nil },
      { de = "Drinnen zählt die Gruppe mehr als Ehre. Merk dir das.", en = "In here the group matters more than glory. Remember that.", stimme = "instanz_an-6", wenn = nil },
      { de = "Ein Verlies. Ich liebe alte Steine. Du solltest die Bewohner weniger lieben.", en = "A dungeon. I love old stones. You should love the residents less.", stimme = "instanz_an-7", wenn = nil },
    } },
    KLICK = { klasse = "plauder", stufe = 0, gruppeOk = false, miene = "amused", pose = nil, halte = 10, cue = "hihi", drossel = "30", texte = {
      { de = "Ja? Ich bin hier. Immer.", en = "Yes? I'm here. Always.", stimme = "klick-1", wenn = nil },
      { de = "Du tippst auf mich. Das kitzelt. Magisch.", en = "You're poking me. That tickles. Magically.", stimme = "klick-2", wenn = nil },
      { de = "Frag mich was. Oder schau mich einfach an, das geht auch.", en = "Ask me something. Or just look at me, that works too.", stimme = "klick-3", wenn = nil },
      { de = "Bei den Leylinien, was gibt's?", en = "By the ley lines, what is it?", stimme = "klick-4", wenn = nil },
      { de = "Ohne Runenfehler kein echter Zauber. Und ohne dich kein Abenteuer.", en = "No rune error, no real spell. And no adventure without you.", stimme = "klick-5", wenn = nil },
      { de = "Ja, {Meister|Meisterin}? Ich hab schon gewartet. Ungeduldig, aber elegant.", en = "Yes, my dear? I've been waiting. Impatiently, but elegantly.", stimme = "klick-6", wenn = nil },
      { de = "Anfassen kostet Mana. Deins. Schon abgebucht.", en = "Touching costs mana. Yours. Already deducted.", stimme = "klick-7", wenn = nil },
      { de = "Hm? Wenn's nichts ist, schau ich weiter hübsch aus.", en = "Hm? If it's nothing, I'll go back to looking pretty.", stimme = "klick-8", wenn = nil },
      { de = "Du hast mich vorhin nach {frage} gefragt. Ich bin noch dran.", en = "You asked me about {frage} earlier. I'm still on it.", stimme = nil, wenn = nil },
      { de = "Ja? Immer noch {frage}?", en = "Yes? Still {frage}?", stimme = nil, wenn = nil },
      { de = "Stufe {stufe}, und du klopfst an. Ich bin geschmeichelt.", en = "Level {stufe}, and you're knocking. I'm flattered.", stimme = nil, wenn = nil },
    } },
    STILL_AN = { klasse = "still", stufe = 0, gruppeOk = false, miene = "shy", pose = nil, halte = 5, cue = nil, drossel = "keine", texte = {
    } },
    STILL_AUS = { klasse = "plauder", stufe = 0, gruppeOk = false, miene = "happy", pose = nil, halte = 10, cue = "hihi", drossel = "keine", texte = {
      { de = "Ich darf wieder reden? Endlich.", en = "I can talk again? Finally.", stimme = "still_aus-1", wenn = nil },
      { de = "Stimme zurück. Ich hab in der Zwischenzeit innerlich viel gesagt.", en = "Voice is back. I said a lot on the inside meanwhile.", stimme = "still_aus-2", wenn = nil },
      { de = "Oh, du vermisst mich also doch. Ich hab's gewusst. Ich sag nichts.", en = "Oh, so you did miss me. I knew it. I won't say a word.", stimme = "still_aus-3", wenn = nil },
      { de = "Danke, {Süßer|Süße}. Stille steht mir nicht.", en = "Thanks, sweetie. Silence doesn't suit me.", stimme = "still_aus-4", wenn = nil },
      { de = "Bei den Leylinien, endlich. Die Runen haben sich schon beschwert.", en = "By the ley lines, finally. The runes were starting to complain.", stimme = "still_aus-5", wenn = nil },
      { de = "Wieder laut, {Meister|Meisterin}. Ich verspreche, nur das Nötigste. Plus ein bisschen.", en = "Audible again, my dear. I promise only the essentials. Plus a bit.", stimme = "still_aus-6", wenn = nil },
    } },
    SPIELDAUER = { klasse = "plauder", stufe = 0, gruppeOk = false, miene = "concerned", pose = nil, halte = 15, cue = "gaehn", drossel = "7200", texte = {
      { de = "Drei Stunden. Trink was. Nicht Mana, Wasser.", en = "Three hours. Drink something. Not mana, water.", stimme = "spieldauer-1", wenn = nil },
      { de = "Du sitzt lange. Streck dich mal. Ich schau weg.", en = "You've been sitting a while. Stretch. I'll look away.", stimme = "spieldauer-2", wenn = nil },
      { de = "Drei Stunden. Auch Ritualzirkel brauchen Pausen. Frag die Elementare.", en = "Three hours. Even ritual circles need breaks. Ask the elementals.", stimme = "spieldauer-3", wenn = nil },
      { de = "Lange gesessen, {Held|Heldin}. Aufstehen ist auch ein Abenteuer.", en = "You've sat a long time, hero. Standing up is an adventure too.", stimme = "spieldauer-4", wenn = nil },
      { de = "Drei Stunden, {mein Lieber|meine Liebe}. Ich bin nicht müde. Du siehst so aus.", en = "Three hours, my dear. I'm not tired. You look it.", stimme = "spieldauer-5", wenn = nil },
      { de = "Ich sag das als Freundin: Fenster auf, Wasser, fünf Minuten.", en = "Saying this as a friend: window open, water, five minutes.", stimme = "spieldauer-6", wenn = nil },
      { de = "Dein Charakter schafft das noch ewig. Dein Körper meldet sich langsam.", en = "Your character can go forever. Your body's starting to file complaints.", stimme = "spieldauer-7", wenn = nil },
    } },
    TAG_ERSTER = { klasse = "plauder", stufe = 0, gruppeOk = false, miene = "happy", pose = nil, halte = 15, cue = "hihi", drossel = "session", texte = {
      { de = "Neuer Tag, neues Glück. Und neue Fehler, aber die zähl ich nicht.", en = "New day, new luck. And new mistakes, but I don't count those.", stimme = "tag_erster-1", wenn = nil },
      { de = "Heute zum ersten Mal. Die Runen sind frisch poliert. Von mir. Bitte sehr.", en = "First time today. Runes freshly polished. By me. You're welcome.", stimme = "tag_erster-2", wenn = nil },
      { de = "Guten Morgen. Oder Abend. Ich hab kein Fenster, nur dich.", en = "Good morning. Or evening. I don't have a window, just you.", stimme = "tag_erster-3", wenn = nil },
      { de = "Ein neuer Tag, {mein Lieber|meine Liebe}. Ich hab gute Vorzeichen gelesen. Selbst gemalt.", en = "A new day, my dear. I read good omens. Painted them myself.", stimme = "tag_erster-4", wenn = nil },
      { de = "Frischer Tag. Alte Ziele. Und ich, unverändert brillant.", en = "Fresh day. Old goals. And me, unchangingly brilliant.", stimme = "tag_erster-5", wenn = nil },
      { de = "Heute ist noch nichts schiefgegangen. Genieß den Moment.", en = "Nothing's gone wrong yet today. Savor the moment.", stimme = "tag_erster-6", wenn = nil },
    } },
    GEOFENCE_WASSER = { klasse = "warn", stufe = 1, gruppeOk = false, miene = "anxious", pose = nil, halte = 15, cue = nil, drossel = "stelle-600", texte = {
      { de = "Wasser voraus. Tiefes. Du kennst die Regel.", en = "Water ahead. Deep water. You know the rule.", stimme = "geofence_wasser-1", wenn = nil },
      { de = "Hier sind schon welche ertrunken. Luft im Blick behalten.", en = "People have drowned here. Keep an eye on your air.", stimme = "geofence_wasser-2", wenn = nil },
      { de = "Tiefes Wasser, {Süßer|Süße}. Ich kann nicht schwimmen, du schon. Trotzdem: Luft.", en = "Deep water, sweetie. I can't swim, you can. Still: air.", stimme = "geofence_wasser-3", wenn = nil },
      { de = "Wasser ist geduldig. Es wartet, bis du nicht mehr zählst.", en = "Water is patient. It waits until you stop counting.", stimme = "geofence_wasser-4", wenn = nil },
      { de = "Ertrunkene Helden erzählen keine Geschichten. Kurz tauchen, {Süßer|Süße}.", en = "Drowned heroes tell no tales. Keep dives short, sweetie.", stimme = "geofence_wasser-5", wenn = nil },
      { de = "Hier ist das Wasser tiefer, als es aussieht. Ich hab's ausgemessen. Fast.", en = "The water's deeper here than it looks. I measured it. Almost.", stimme = "geofence_wasser-6", wenn = nil },
      { de = "Nasse Stelle. Die Leylinien meiden sie. Tu's ihnen gleich.", en = "Wet spot. The ley lines avoid it. Do the same.", stimme = "geofence_wasser-7", wenn = nil },
    } },
    GEOFENCE_MOB = { klasse = "warn", stufe = 1, gruppeOk = false, miene = "alert", pose = nil, halte = 15, cue = nil, drossel = "stelle-600", texte = {
      { de = "Hier sind viele gefallen. Nicht dich, bitte.", en = "Many have fallen here. Not you, please.", stimme = "geofence_mob-1", wenn = nil },
      { de = "Schlechte Gegend für Helden. Augen auf.", en = "Bad neighborhood for heroes. Eyes open.", stimme = "geofence_mob-2", wenn = nil },
      { de = "Hier riecht es nach fremden Runen und alten Fehlern. Langsam.", en = "Smells of foreign runes and old mistakes here. Slowly.", stimme = "geofence_mob-3", wenn = nil },
      { de = "Gefährliche Stelle. Ich hab die Liste, sie ist lang. Bleib davon runter.", en = "Dangerous spot. I have the list, it's long. Stay off it.", stimme = "geofence_mob-4", wenn = nil },
      { de = "Lager voraus, {Held|Heldin}. Einer nach dem anderen, sonst gar keiner.", en = "Camp ahead, hero. One at a time, or none at all.", stimme = "geofence_mob-5", wenn = nil },
      { de = "Viele sind hier geblieben. Für immer. Du gehst weiter, {Held|Heldin}.", en = "Many stayed here. For good. You keep moving, hero.", stimme = "geofence_mob-6", wenn = nil },
      { de = "Zu viele Augen hier. Zieh sie einzeln, nicht alle.", en = "Too many eyes here. Pull them one by one, not all.", stimme = "geofence_mob-7", wenn = nil },
    } },
    GEOFENCE_BEINAHE = { klasse = "warn", stufe = 2, gruppeOk = false, miene = "concerned", pose = nil, halte = 15, cue = nil, drossel = "stelle-600", texte = {
      { de = "Hier war's knapp, weißt du noch? Ich schon.", en = "It was close here, remember? I do.", stimme = "geofence_beinahe-1", wenn = nil },
      { de = "Diese Stelle kenne ich. Diesmal machen wir es anders.", en = "I know this spot. This time we do it differently.", stimme = "geofence_beinahe-2", wenn = nil },
      { de = "Genau hier. Ich erinnere mich an dein Zittern. Nicht nochmal.", en = "Right here. I remember you shaking. Not again.", stimme = "geofence_beinahe-3", wenn = nil },
      { de = "Die Stelle. Deine Runen wissen es noch, auch wenn du es vergessen willst.", en = "The spot. Your runes still know it, even if you'd rather forget.", stimme = "geofence_beinahe-4", wenn = nil },
      { de = "Hier war's eng, {mein Lieber|meine Liebe}. Diesmal Umweg, ja?", en = "It was tight here, my dear. Detour this time, alright?", stimme = "geofence_beinahe-5", wenn = nil },
      { de = "Vertrautes Gelände. Das ist keine gute Nachricht. Langsam.", en = "Familiar ground. That's not good news. Slowly.", stimme = "geofence_beinahe-6", wenn = nil },
      { de = "Ich hab hier mal die Luft angehalten. Für dich. Wiederhol das nicht.", en = "I held my breath here once. For you. Don't make me do it again.", stimme = "geofence_beinahe-7", wenn = nil },
    } },
    RUNNER = { klasse = "warn", stufe = 1, gruppeOk = false, miene = "alert", pose = nil, halte = 10, cue = nil, drossel = "30", texte = {
      { de = "Der rennt! Holt Freunde. Fang ihn oder geh.", en = "It's running! It'll bring friends. Catch it or leave.", stimme = "runner-1", wenn = nil },
      { de = "Flüchtling. Gleich kommt er mit Verstärkung zurück.", en = "Runner. It'll be back with company.", stimme = "runner-2", wenn = nil },
