    RUECKKEHR = { klasse = "plauder", stufe = 0, gruppeOk = false, miene = "happy", pose = nil, halte = 10, cue = "hihi", drossel = "1800", texte = {
      { de = "Da bist du wieder. Ich hab die Runen gezählt. Zweimal.", en = "There you are again. I counted the runes. Twice.", stimme = "rueckkehr-1", wenn = nil },
      { de = "Ich dachte schon, du hättest mich vergessen. Hätte mich nicht gestört. Kein bisschen.", en = "I was starting to think you'd forgotten me. Wouldn't have bothered me. Not a bit.", stimme = "rueckkehr-2", wenn = nil },
      { de = "Zurück. Gut. Das Mana war schon ganz unruhig.", en = "Back. Good. The mana was getting restless.", stimme = "rueckkehr-3", wenn = nil },
      { de = "{minuten} Minuten. Ich hab mitgezählt. Aus Langeweile, nicht aus Sorge.", en = "{minuten} minutes. I counted. Out of boredom, not worry.", stimme = nil, wenn = { vertraut = 2 } },
      { de = "Da bist du. Ich hab die Runen warm gehalten, {Held|Heldin}.", en = "There you are. I kept the runes warm, hero.", stimme = "rueckkehr-4", wenn = { vertraut = 3 } },
    } },
    SPAET = { klasse = "plauder", stufe = 0, gruppeOk = false, miene = "hmm", pose = nil, halte = 12, cue = "gaehn", drossel = "session", texte = {
      { de = "Es ist nach Mitternacht, {Held|Heldin}. Selbst die Leylinien sind leiser geworden.", en = "It's past midnight, hero. Even the ley lines have gone quiet.", stimme = "spaet-1", wenn = nil },
      { de = "Ich sag nichts. Ich schau dich nur an. So lange, bis du es selbst merkst.", en = "I'm not saying anything. I'm just looking at you. Until you notice it yourself.", stimme = "spaet-2", wenn = nil },
      { de = "Die Runen schlafen um diese Zeit. Sie sind darin klüger als wir beide.", en = "The runes sleep at this hour. They're wiser than either of us that way.", stimme = "spaet-3", wenn = nil },
      { de = "Nach Mitternacht und {stunden} Stunden am Stück. Ich zähle nur, ich urteile nicht.", en = "Past midnight and {stunden} hours straight. I'm only counting, not judging.", stimme = nil, wenn = { sitzung = 3 } },
      { de = "Ich kenne dich lang genug, um zu wissen, dass „nur noch eine Quest“ gelogen ist.", en = "I know you well enough to know that \"just one more quest\" is a lie.", stimme = "spaet-4", wenn = { vertraut = 2 } },
    } },
    JAHRESTAG = { klasse = "plauder", stufe = 0, gruppeOk = false, miene = "overjoyed", pose = nil, halte = 15, cue = "hihi", drossel = "session", texte = {
      { de = "Heute ist ein Jahrestag. Deiner. Ich habe ihn mir gemerkt, weil du es nicht tust.", en = "Today is an anniversary. Yours. I remembered it because you don't.", stimme = "jahrestag-1", wenn = nil },
      { de = "Ein Jahr. Ein ganzes Jahr, und du lebst noch. Ich nehme etwas Anteil daran.", en = "One year. A whole year, and you're still alive. I take some credit for that.", stimme = "jahrestag-2", wenn = nil },
      { de = "Heute vor langer Zeit hab ich dich zum ersten Mal gesehen. Du warst kleiner. Und lauter.", en = "A long time ago today I saw you for the first time. You were smaller. And louder.", stimme = "jahrestag-3", wenn = nil },
      { de = "Heute vor {tage} Tagen hab ich dich zum ersten Mal gesehen. Ob du vorher existiert hast, weiß ich nicht.", en = "{tage} days ago today I saw you for the first time. Whether you existed before that, I couldn't say.", stimme = nil, wenn = nil },
      { de = "{jahre} Jahre, {Held|Heldin}. Ich sage das nur einmal, also hör hin: gut gemacht.", en = "{jahre} years, hero. I'll say this once, so listen: well done.", stimme = nil, wenn = { vertraut = 2 } },
    } },
    GEDENKEN = { klasse = "plauder", stufe = 0, gruppeOk = false, miene = "touched", pose = nil, halte = 20, cue = nil, drossel = "session", texte = {
      { de = "Ein Jahrestag, den niemand feiert. Ich erwähne ihn trotzdem. Einmal.", en = "An anniversary nobody celebrates. I'm mentioning it anyway. Once.", stimme = "gedenken-1", wenn = nil },
      { de = "Heute ist so ein Tag. Ich bin kurz still. Du darfst auch.", en = "Today is one of those days. I'll be quiet for a moment. You may too.", stimme = "gedenken-2", wenn = nil },
      { de = "Ich vergesse niemanden, den ich begleitet habe. Das ist keine Wehmut, das ist Buchhaltung.", en = "I don't forget anyone I've walked with. That isn't melancholy, that's bookkeeping.", stimme = "gedenken-3", wenn = nil },
      { de = "Heute vor einem Jahr ist {vorgaenger} gefallen. Ich wollte, dass du es weißt.", en = "A year ago today, {vorgaenger} fell. I wanted you to know.", stimme = nil, wenn = nil },
      { de = "{vorgaenger}. {jahre} Jahre. Ich hab die Stelle noch im Kopf, {Held|Heldin}.", en = "{vorgaenger}. {jahre} years. I still remember the spot, hero.", stimme = nil, wenn = { vertraut = 2 } },
    } },
    FEIERTAG = { klasse = "plauder", stufe = 0, gruppeOk = false, miene = "amused", pose = nil, halte = 12, cue = nil, drossel = "session", texte = {
      { de = "Es ist Festzeit. Man merkt es an den Farben und daran, dass alle freundlicher lügen.", en = "It's festival season. You can tell by the colours and by how kindly everyone lies.", stimme = "feiertag-1", wenn = nil },
      { de = "Feiertag. Ich feiere nicht, ich kommentiere. Das ist mein Beitrag.", en = "A holiday. I don't celebrate, I comment. That's my contribution.", stimme = "feiertag-2", wenn = nil },
      { de = "Heute ist etwas los da draußen. Geh hin, {Held|Heldin}, ich pass auf die Runen auf.", en = "Something's going on out there today. Go, hero, I'll watch the runes.", stimme = "feiertag-3", wenn = nil },
      { de = "Winterhauch. Die Runen riechen nach Zimt. Frag nicht, wie das geht.", en = "Winter Veil. The runes smell of cinnamon. Don't ask how that works.", stimme = "feiertag-4", wenn = { fest = "winterhauch" } },
      { de = "Schlotternächte. Endlich eine Jahreszeit, in der ich nicht die Unheimlichste bin.", en = "Hallow's End. Finally a season where I'm not the creepiest thing around.", stimme = "feiertag-5", wenn = { fest = "schlotternaechte" } },
      { de = "Liebe liegt in der Luft. Und Parfüm. Vor allem Parfüm. Ich halte Abstand.", en = "Love is in the air. And perfume. Mostly perfume. I'm keeping my distance.", stimme = "feiertag-6", wenn = { fest = "liebe" } },
      { de = "Sonnenwende. Feuer, überall Feuer. Das ist mein Fest, {Held|Heldin}, ich sag es ungern.", en = "Midsummer. Fire, fire everywhere. This one's my festival, hero, I hate to admit it.", stimme = "feiertag-7", wenn = { fest = "sonnenwende" } },
    } },
    EMOTE = { klasse = "plauder", stufe = 0, gruppeOk = false, miene = "amused", pose = nil, halte = 8, cue = nil, drossel = "60", texte = {
      { de = "Ich hab das gesehen. Ich sehe alles. Das ist quasi mein Beruf.", en = "I saw that. I see everything. It's basically my job.", stimme = "emote-1", wenn = nil },
      { de = "War das für mich? Bei den Leylinien. Na gut.", en = "Was that for me? By the ley lines. Fine.", stimme = "emote-2", wenn = nil },
      { de = "Ich reagiere jetzt nicht darauf. Das hier ist keine Reaktion.", en = "I am not reacting to that. This is not a reaction.", stimme = "emote-3", wenn = nil },
      { de = "Winkst du mir? Ich hab die ganze Zeit hier gestanden. Aber hallo auch.", en = "Are you waving at me? I've been standing right here the whole time. But hello to you too.", stimme = "emote-4", wenn = { emote = "wave" } },
      { de = "Ich bin aus Runen. Da geht das nicht. Trotzdem — danke. Ähm.", en = "I'm made of runes. That doesn't work. Still — thank you. Um.", stimme = "emote-5", wenn = { emote = "hug" } },
      { de = "Bitte. Und jetzt schau nicht so, sonst gewöhn ich mich dran.", en = "You're welcome. Now stop looking at me like that or I'll get used to it.", stimme = "emote-6", wenn = { emote = "thank" } },
      { de = "Tanz du nur. Ich schwebe hier und bewerte. Das ist die bessere Rolle.", en = "You dance. I'll hover here and judge. That's the better role.", stimme = "emote-7", wenn = { emote = "dance" } },
      { de = "Hey. Was ist los? Ich bin schlecht in so etwas, aber ich bin da.", en = "Hey. What's wrong? I'm bad at this sort of thing, but I'm here.", stimme = "emote-8", wenn = { emote = "cry" } },
      { de = "Schlaf ruhig. Ich wecke dich, wenn etwas mit Zähnen kommt.", en = "Sleep. I'll wake you if something with teeth turns up.", stimme = "emote-9", wenn = { emote = "sleep" } },
    } },
    LAGERFEUER = { klasse = "plauder", stufe = 0, gruppeOk = false, miene = "touched", pose = nil, halte = 18, cue = nil, drossel = "session", texte = {
      { de = "Setz dich. Das Feuer hält noch. Und ich erzähl nichts, wenn du nicht willst.", en = "Sit down. The fire will hold. And I won't tell any stories unless you want me to.", stimme = "lagerfeuer-1", wenn = nil },
      { de = "Feuer. Endlich mal eines, das niemandem gehört, der uns umbringen will.", en = "Fire. Finally one that doesn't belong to someone trying to kill us.", stimme = "lagerfeuer-2", wenn = nil },
      { de = "Ich mag Feuer. Es ist die einzige Magie, die jeder versteht.", en = "I like fire. It's the only magic everyone understands.", stimme = "lagerfeuer-3", wenn = nil },
      { de = "Feuer. Gut. Weißt du noch, {erinnerung}? Ich schon.", en = "Fire. Good. Do you remember {erinnerung}? I do.", stimme = nil, wenn = { vertraut = 1 } },
      { de = "Am Feuer redet man. Also: {erinnerung}. Das wollte ich nur mal gesagt haben.", en = "People talk by the fire. So: {erinnerung}. I just wanted that said.", stimme = nil, wenn = { vertraut = 2 } },
    } },
